const e=$json; if(!e||e.type!=='crowdrelay.outreach.requested'||e.version!==1) return []; const d=e.data??{}; if(!d.action_id||!d.target_id||!d.target_name||!d.phase||!d.template_key) throw new Error('Invalid outreach intent'); const routes=JSON.parse($env.VIRYA_OUTREACH_FORM_ROUTES_JSON||'{}'); const route=routes[String(d.target_id)]??null; const pitchTitle=$env.VIRYA_CURRENT_PITCH_TITLE; const pitchUrl=$env.VIRYA_CURRENT_PITCH_URL; const epkUrl=$env.VIRYA_EPK_URL; if(!pitchTitle||!pitchUrl||!epkUrl) throw new Error('Missing pitch configuration'); const isPlaylist=String(d.target_template_key||d.template_key).includes('playlist'); const purpose=isPlaylist?'playlist consideration':'coverage / collaboration'; const intro=d.phase==='follow_up'?'Quick follow-up on the note below.':'I am writing from VIRYA, a modern metal band from Wrocław.'; const subject=(d.phase==='follow_up'?'Follow-up: ':'')+`VIRYA — ${pitchTitle}`; const body=`Hi ${d.target_name},

