Best,
VIRYA`; return [{json:{event_id:e.id,action_id:String(d.action_id),target_id:String(d.target_id),target_name:d.target_name,contact_email:d.contact_email||'',phase:d.phase,template_key:d.template_key,target_template_key:d.target_template_key||'',route,pitch_title:pitchTitle,pitch_url:pitchUrl,epk_url:epkUrl,subject,body}}];
